def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        total_seconds = nanoseconds // 1_000_000_000
        hundred_nanos = nanoseconds % 1_000_000_000

        hours = int(total_seconds // 3600) % 24
        minutes = int((total_seconds % 3600) // 60)
        seconds = int(total_seconds % 60)

        if hundred_nanos == 0:
            time_part = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
        else:
            time_part = f"{hours:02d}:{minutes:02d}:{seconds:02d}.{hundred_nanos//100:06d}".rstrip('0').rstrip('.')

        if tz is not None:
            return f"{time_part},{tz}"
        else:
            return time_part
    except (TypeError, ValueError, OverflowError):
        raise ValueError("Invalid nanoseconds or timezone values")

