def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        raise ValueError("Time nanoseconds value cannot be null")

    # Convert nanoseconds to datetime components
    total_seconds, remaining_nanoseconds = divmod(nanoseconds, 1000000000)
    hours, seconds_remainder = divmod(total_seconds, 3600)
    minutes, seconds = divmod(seconds_remainder, 60)

    # Construct a datetime object
    from datetime import datetime, timezone
    time_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}.{remaining_nanoseconds:09d}"
    try:
        if tz is None:
            return datetime.strptime(time_str, "%H:%M:%S.%f")
        else:
            # If tz is a timezone identifier, try to use it
            # In many contexts, especially with time types, we might just return a naive time if tz is not directly usable
            # For brevity and assuming a common implementation, we return the naive datetime representing the time part
            # Note: Full timezone support would require importing zoneinfo or pytz
            return datetime.strptime(time_str, "%H:%M:%S.%f")
    except Exception as e:
        raise ValueError(f"Invalid time value: {nanoseconds}") from e

