def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    from zope.interface import ObjectSpecification, Specification

    if isinstance(object, type):
        iface = ObjectSpecification
    else:
        iface = ObjectSpecification

    spec = getattr(object, '__spec__', None)
    if spec is not None:
        return spec

    try:
        # For classes, get the __implemented__ attribute
        interfaces = object.__implemented__
    except AttributeError:
        try:
            # For instances, get the __provides__ attribute
            interfaces = object.__provides__
        except AttributeError:
            return Specification()

    return Specification(base=object, bases=tuple(interfaces))

