def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    minimal = []
    for cls in classes:
        if not minimal:
            minimal.append(cls)
            continue
        # Check if this class is already implied by any class in minimal
        implied = False
        for existing in minimal:
            if issubclass(cls, existing):
                implied = True
                break
        # Check if this class implies any existing class in minimal
        if not implied:
            # Remove existing classes that are subclasses of cls
            minimal = [existing for existing in minimal if not issubclass(existing, cls)]
            minimal.append(cls)

    return minimal

