def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Preserve order while removing duplicates
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Remove any class that is a subclass of another class in the list
    # because if A is a base of B, then including both A and B is redundant;
    # we only need B (the more specialized class).
    # We iterate and check for each class if it's a proper subclass of any other class in the list
    # If so, we drop it from the list.
    minimal = []
    for i, cls in enumerate(unique_classes):
        # Check if there's another class in the list that cls subclasses
        dominant = False
        for j, other in enumerate(unique_classes):
            if i != j and issubclass(cls, other):
                dominant = True
                break
        if not dominant:
            minimal.append(cls)

    return minimal

