def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        bins = np.asarray(bins)
        edges = np.asarray(edges)
    except Exception:
        raise TypeError("Both 'bins' and 'edges' must be array-like objects.")

    if bins.ndim != 2:
        raise ValueError("'bins' must be a 2D array of shape (N, 2) or similar for integration limits.")

    if edges.ndim != 1:
        raise ValueError("'edges' must be a 1D array of bin boundaries.")

    if bins.shape[1] != 2:
        raise ValueError("Each bin must have two values (minimum and maximum).")

    Nbins = len(edges) - 1

    if Nbins <= 0:
        return 0.0

    if len(bins) > Nbins:
        raise ValueError("Number of bins in data exceeds number of integration mesh bins.")

    integral = 0.0

    for i in range(Nbins):
        edge_start = edges[i]
        edge_stop  = edges[i+1]

        if edge_stop < bins[i,0] or edge_start > bins[i,1]:
            continue
        else:
            igz = bins[i, 0] < edge_start 
            bmin = np.where(igz, edge_start, bins[i, 0])
            bmax = np.where(igz, bins[i, 1], edge_stop)
            integral += (bmax - bmin)

    return integral

