def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    from krake.data.kubernetes import ResourceType

    if not hasattr(app.spec, 'manifest'):
        raise AttributeError("Application spec does not have a 'manifest' attribute.")

    manifest = app.spec.manifest

    for resource_name, resource in manifest.resources.items():
        resource_type = resource.type
        observer = resource.properties.get('observer')

        if observer is None:
            if resource_type == ResourceType.INGRESS:
                continue
            elif resource_type in [
                ResourceType.SERVICE,
                ResourceType.POD,
                ResourceType.OPERATOR
            ]:
                resource.properties['observer'] = {
                    'schema': default_observer_schema[resource_type],
                }
            else:
                raise UnsupportedResourceType(
                    f"Resource type {resource_type} is not supported by the observer mechanism."
                )

