def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Handle the case where self is not of a type that supports conversion
    # or is a special type, ensuring robustness against different input types.
    indent_str = ' ' * indent

    # Define a recursive helper to traverse objects and produce formatted output
    def repr_object(obj, indent_level=0, seen=None):
        if seen is None:
            seen = set()

        current_indent = ' ' * (indent_level * 2)
        next_indent = ' ' * ((indent_level + 1) * 2)

        obj_id = id(obj)
        if obj_id in seen:
            return current_indent + '[...]'

        new_seen = seen.copy()
        new_seen.add(obj_id)

        # Check for basic types
        if isinstance(obj, (str, int, float, bool, bytes)):
            return current_indent + repr(obj)

        if obj is None:
            return current_indent + 'None'

        # Check for collections
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                return current_indent + type(obj).__name__.lower() + '()'
            if debug:
                type_name = type(obj).__name__
                if type_name == 'set':
                    type_name = 'set'
                lines = [current_indent + type_name + '(']
                for item in list(obj):
                    lines.append(' ' + repr_object(item, indent_level + 1, new_seen))
                if lines:
                    lines[-1] = lines[-1] + ','
                lines.append(current_indent + ')')
                return '\n'.join(lines)
            else:
                items = ', '.join(repr_object(item, indent_level + 0, new_seen).strip() for item in obj)
                return current_indent + type(obj).__name__.lower() + '([' + items + '])'

        if isinstance(obj, dict):
            if not obj:
                return current_indent + 'dict()'
            lines = [current_indent + 'dict(']
            for key, value in obj.items():
                key_repr = repr_object(key, indent_level + 1, new_seen)
                value_repr = repr_object(value, indent_level + 1, new_seen)
                lines.append('    ' + key_repr.replace('\n', ' ') + ': ' + value_repr.replace('\n', ' ') + ',')
            if lines:
                lines[-1] = lines[-1] + ''
            lines.append(current_indent + ')')
            return '\n'.join(lines)

        # Handle objects with a __dict__ attribute
        if hasattr(obj, '__dict__'):
            obj_type = type(obj).__name__
            lines = [current_indent + obj_type + '(']
            if debug:
                for key, value in obj.__dict__.items():
                    value_repr = repr_object(value, indent_level + 1, new_seen)
                    lines.append('    ' + key + ': ' + value_repr.replace('\n', ' ') + ',')
            if lines:
                lines[-1] = lines[-1] + ')'
            return '\n'.join(lines)

        # Fallback to repr
        return current_indent + repr(obj)

    return repr_object(self, 0, seen=set())

