    """Call the given command(s)."""
    full_commands = _map_commands(commands, args, cwd)
    stdout = None  # start with stdout, next pass get stderr
    missing = []
    # here we try to run the commands,
    # if a command fails, we add the failed command to `missing`
    # for subsequent cwd's
    # if the combined output is not empty, return the overall content
    for full_cmd in full_commands:
        for cmd in full_cmd:
