                             cwd=cwd,
                             env=env,
                             stdout=PIPE,
                             stderr=(PIPE if hide_stderr else None))
            except OSError as e:
                missing.append(cmd)
                cmd, args = _split_command(cmd)
                if verbose:
                    print(_("Error: Command {} failed with error code {}".format(cmd, e.errno)), file=sys.stderr)
            else:
                stdout, _ = proc.communicate()
