def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    def print_running_command(commands, cwd):
        """Print the command being run."""
        print_running_command = " ".join(commands)
        if cwd:
            print_running_command = "cd %s && %s" % (cwd, print_running_command)
        print(print_running_command)

    def raise_run_command_error(returncode, commands, out, verbose):
        """Raise an error if the command failed."""
        err = RuntimeError("failed to run command: %s" % commands)
        if verbose:
            err = RuntimeError("failed to run command: %s\n%s" % (commands, out))
        err.returncode = returncode
        err.commands = commands
        err.out = out
        raise err
    if not commands:
        raise ValueError("no commands were provided")

    # Build the list of commands
    # If the commands are a string, split them
    if isinstance(commands, str):
        commands = shlex.split(commands)
    else:
        commands = list(commands)

    # Append the arguments
    commands.extend(args)

    # Set up the environment
    if env is None:
        env = os.environ.copy()
    else:
        env = env.update(os.environ)

    # Run the command
    if verbose:
        print_running_command(commands, cwd)

    try:
        if hide_stderr:
            p = subprocess.Popen(
                commands,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                cwd=cwd,
                env=env,
            )
        else:
            p = subprocess.Popen(
                commands,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                cwd=cwd,
                env=env,
            )

        out, _ = p.communicate()

        if p.returncode != 0:
            raise_run_command_error(
                p.returncode, commands, out, verbose
            )

        return out

    except OSError as e:
        raise OSError("failed to run command: %s\n%s" % (commands, e))

