def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    # these are settable from the distutils.setup() config
    cfg = Config()
    cfg.VCS = get_setup_cfg("versioneer", "VCS") or cfg.VCS

    try:
        from configparser import ConfigParser
    except ImportError:
        from ConfigParser import ConfigParser

    have_pyproject = False

    # configuration from .pyproject.toml
    try:
        import tomli
    except ImportError:
        try:
            import tomllib as tomli
        except ImportError:
            tomli = None
    if tomli is not None:
        try:
            with open("pyproject.toml", "rb") as fobj:
                toml_dict = tomli.load(fobj)
            have_pyproject = True
            tool_cfg = toml_dict.get("tool", {}).get("versioneer", {})
            for key in tool_cfg:
                attribute = key.replace("-", "_")
                if hasattr(cfg, attribute):
                    value = tool_cfg[key]
                    setattr(cfg, attribute, value)
        except (OSError, tomli.TOMLDecodeError):
            pass

    # minimal config
    cfg.parentdir = whereami()
    if not cfg.versionfile_source:
        guess = guess_config()
        if guess:
            guess.VCS = cfg.VCS
            cfg.versionfile_source = guess.versionfile_source
            cfg.tag_prefix = guess.tag_prefix

    # cfg.setup_py = os.path.join(cfg.parentdir, "setup.py")

    cfg.style = cfg.style or "pep440"
    return cfg

