            args_dict = vars(args)
            args_dict.update(vars(parser.parse_args(unknown, namespace=args)))
            if subparser_selected:
                return {subparser: args_dict}
        return {'global': args}
    except Exception as e:
        raise ValueError(f"Error parsing arguments: {e}")

