def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Determine the destination directory
    if filename is None:
        # Use a unique temporary directory name based on the archive name
        base_name = os.path.splitext(os.path.basename(archive_path))[0]
        dest_dir = os.path.join(str(tmp_path), base_name)
    else:
        dest_dir = filename

    # Ensure the destination directory is empty or does not exist
    if os.path.exists(dest_dir):
        if os.listdir(dest_dir):
            raise ValueError(f"Directory {dest_dir} is not empty")
    else:
        os.makedirs(dest_dir, exist_ok=True)

    # Determine the archive type and extract accordingly
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        subprocess.run(
            ['tar', '-xzf', archive_path, '-C', dest_dir],
            check=True
        )
    elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
        subprocess.run(
            ['tar', '-xjf', archive_path, '-C', dest_dir],
            check=True
        )
    elif archive_path.endswith('.zip'):
        subprocess.run(
            ['unzip', '-d', dest_dir, archive_path],
            check=True
        )
    elif archive_path.endswith('.tar'):
        subprocess.run(
            ['tar', '-xf', archive_path, '-C', dest_dir],
            check=True
        )
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    return f"file://{dest_dir}"

