    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    if not ignored:
        return ""

    try:
        # Use git ls-files with --others and --exclude-standard to get ignored/untracked files
        # Then filter to only include those that are actually ignored (not just untracked)
        # A file is ignored if GIT_CHECKEDOUT=0 and it appears in git check-ignore with --no-index
        command = ["git", "ls-files", "--others", "--exclude-standard"]
        result = subprocess.run(command, capture_output=True, text=True, check=True)
        files = result.stdout.strip().splitlines()

        if not files:
            return ""

        ignore_list = []
        for filename in files:
            try:
                # Check if the file is ignored by git
                check_result = subprocess.run(
                    ["git", "check-ignore", "--no-index", "--standard", filename],
                    capture_output=True, text=True
                )
                # If exit code is 0, the file is ignored
                if check_result.returncode == 0:
                    ignore_list.append(filename)
            except Exception:
                continue

        ignore_list.sort()
        return ",".join(ignore_list)
    except Exception as e:
        # Return empty string on any error
        return ""

