def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    def is_glob_pattern(s):
        # Check for shell glob characters: *, ?, [
        return any(c in s for c in ['*', '?', '['])

    def expand_for_shell(path):
        # If the path is a glob pattern, leave it as is.
        if is_glob_pattern(path):
            return path
        sh_base = 'sh:'
        return f'{sh_base}**/*{path}*/**'

    def expand_location(path):
        location = None
        for loc in path.split('/'):
            if loc.startswith('pp'):
                location = loc
                break
        if location is None:
            return []
        mask = re.sub(r'pp:', 'pp', location)
        return [mask]

    def path_loop(paths):
        for path in paths:
            # First, try to expand as a location
            expanded_location = expand_location(path)
            if len(expanded_location) > 0:
                yield from expanded_location
                continue
            # If not a path containing a location, process it as a shell pattern
            yield expand_for_shell(path)

    return list(path_loop(find_paths))

