def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    if not isinstance(shape, tuple):
        raise TypeError("shape must be a tuple")
    if len(shape) < 1 or len(shape) > 2:
        raise ValueError("shape must have exactly one or two dimensions")
    for dim in shape:
        if not isinstance(dim, int) or dim < 0:
            raise TypeError("each dimension in shape must be a non-negative integer")
    try:
        if len(shape) == 1:
            return np.zeros(shape, dtype=dtype)
        else:
            return np.zeros((shape[0], shape[1]), dtype=dtype)
    except Exception as e:
        raise ValueError(f"Failed to create array: {e}")

