      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative:
        # Always check the 'real' provider, in case the candidate itself
        # doesn't consider itself a real provider (e.g., for adapter
        # testing).
        if not iface.providedBy(candidate):
            # We have canonical names to show to people:
            raise Invalid(
                _('%r does not implement %s')
                % (safe_repr(candidate), iface),
            )

    errors = []

    for name in iface:
        attr_def = iface[name]

        # Look at the candidate
        if isinstance(attr_def, InformationElement):
            candidate_attr = getattr(candidate, name, None)
            if candidate_attr is None:
                errors.append('%r required for %r (as %r)' % (
                    attr_def, candidate, name,
                ))
            else:
                try:
                    # Let's see if it's callable
                    eg(IFace = iface, ICandidate = iface(candidate), name=name)
                except Exception:
                    # Don't attempt to call it
                    pass
                else:
                    try:
                        # Try it
                        candidate_attr(*iface[name].__argspec__.a_values)
                    except TypeError as e:
                        errors.append('%r of %r does not match signature of %r: %s' % (
                            name, candidate, iface, e,
                        ))
                    except Exception as e:
                        errors.append('%r of %r raised an exception: %s' % (
                            name, candidate, e,
                        ))
        else:
            # It's a property or attribute
            if not hasattr(candidate, name):
                errors.append('%r required for %r (as %r)' % (
                    attr_def, candidate, name,
                ))

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

