def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not handle:
        return None

    # Split the handle into user and host
    if "@" in handle:
        parts = handle.split("@", 1)
        if len(parts) != 2:
            return None
        user_part, host_part = parts
    else:
        # If no @ sign, assume it's already a host (less common)
        user_part = None
        host_part = handle

    # Construct the webfinger URL
    base_url = "https://{}".format(host_part)
    resource = "acct:{}".format(handle)
    url = "{}/.well-known/webfinger?resource={}".format(base_url, quote(resource))

    try:
        response = requests.get(url)
        if response.status_code == 200:
            return response.text
        else:
            return None
    except Exception:
