    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    if not ir_workspace:
        raise ValueError("ir_workspace cannot be None")
    if not ir_plugin:
        raise ValueError("ir_plugin cannot be None")
    if not playbook_path:
        raise ValueError("playbook_path cannot be None or empty")

    command = ['ansible-playbook']

    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer")
        command.append('-' + 'v' * verbose)

    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dictionary")
        if extra_vars:
            vars_str = ' '.join(f'@{k}={v}' for k, v in extra_vars.items())
            command.extend(['--extra-vars', vars_str])

    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dictionary")
        for flag, value in ansible_args.items():
            if isinstance(value, (list, tuple)):
                if value:
                    command.append(flag)
                    command.extend(str(v) for v in value)
            else:
                if value is not None:
                    command.append(flag)
                    command.append(str(value))

    command.append(playbook_path)

    try:
        output = subprocess.check_output(command, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"ansible-playbook failed with exit code {e.returncode}\nOutput: {e.output.decode()}")
    except FileNotFoundError:
        raise EnvironmentError("ansible-playbook command not found. Please ensure Ansible is installed.")

    return output.decode()

